const job = $input.item.json;
const errors = [];

if (!job.jobId) errors.push('MISSING_JOB_ID');
if (!job.customerId) errors.push('MISSING_CUSTOMER_ID');
if (!job.customerName) errors.push('MISSING_CUSTOMER_NAME');

const jobValueNum = Number(job.jobValue);
const jobValueInvalid = job.jobValue === undefined || job.jobValue === null || job.jobValue === '' || isNaN(jobValueNum) || jobValueNum <= 0;
if (jobValueInvalid) errors.push('INVALID_JOB_VALUE');

const hasCustomerEmail = !!job.customerEmail;

return [{
  json: {
    ...job,
    jobValue: isNaN(jobValueNum) ? 0 : jobValueNum,
    hasCustomerEmail,
    isValid: errors.length === 0,
    validationErrors: errors,
  }
}];

const job = $input.item.json;
return [{ json: {
  status: 'rejected',
  reason: 'validation_failed',
  jobId: job.jobId || null,
  errors: job.validationErrors,
} }];

const config = $input.item.json;
const job = $('Validate Job Data').item.json;
return [{ json: { ...job, ...config } }];

const d = $input.item.json;
const discountPercent = Number(d.discountPercent) || 0;
const rawValue = Number(d.jobValue) || 0;
const discountedValue = Math.round(rawValue * (1 - discountPercent / 100) * 100) / 100;

const useMilestone = !!(d.milestoneInvoicingEnabled && d.milestoneNumber);
const invoiceReference = useMilestone ? `${d.jobId}-M${d.milestoneNumber}` : `${d.jobId}`;
const milestoneLabelText = (useMilestone && d.milestoneLabel) ? ` (${d.milestoneLabel})` : '';
const lineDescription = `${d.jobDescription || 'Completed job'}${milestoneLabelText} - ${d.clientName}`;

return [{
  json: {
    ...d,
    lineAmount: discountedValue,
    invoiceReference,
    lineDescription,
  }
}];

const d = $input.item.json;
const tz = d.sendWindowTimezone || 'UTC';
const now = new Date();

function getParts(date, timeZone) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit'
  });
  const parts = {};
  for (const p of dtf.formatToParts(date)) {
    if (p.type !== 'literal') parts[p.type] = parseInt(p.value, 10);
  }
  if (parts.hour === 24) parts.hour = 0;
  return parts;
}

function getOffsetMinutes(date, timeZone) {
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone, timeZoneName: 'shortOffset' });
  const tzPart = dtf.formatToParts(date).find(p => p.type === 'timeZoneName').value;
  const m = tzPart.match(/GMT([+-]\d+)(?::(\d+))?/);
  if (!m) return 0;
  const h = parseInt(m[1], 10);
  const mm = m[2] ? parseInt(m[2], 10) : 0;
  return h * 60 + (h < 0 ? -mm : mm);
}

const nowParts = getParts(now, tz);
const nowMinutes = nowParts.hour * 60 + nowParts.minute;

const [startH, startM] = (d.sendWindowStart || '00:00').split(':').map(Number);
const [endH, endM] = (d.sendWindowEnd || '23:59').split(':').map(Number);
const startMinutes = startH * 60 + startM;
const endMinutes = endH * 60 + endM;

const inWindow = nowMinutes >= startMinutes && nowMinutes <= endMinutes;

let resumeAt = null;
if (!inWindow) {
  let targetY = nowParts.year, targetM = nowParts.month, targetD = nowParts.day;
  if (nowMinutes > endMinutes) {
    const nextDay = new Date(Date.UTC(nowParts.year, nowParts.month - 1, nowParts.day + 1));
    targetY = nextDay.getUTCFullYear(); targetM = nextDay.getUTCMonth() + 1; targetD = nextDay.getUTCDate();
  }
  const offsetMin = getOffsetMinutes(now, tz);
  const utcMs = Date.UTC(targetY, targetM - 1, targetD, startH, startM) - offsetMin * 60000;
  resumeAt = new Date(utcMs);
}

return [{ json: { ...d, inSendWindow: inWindow, resumeAt: resumeAt ? resumeAt.toISOString() : null } }];

const items = $input.all();
const first = items[0].json;
const list = Array.isArray(first) ? first : [first];
const tenantId = list[0] ? list[0].tenantId : null;
const prior = $('Check Send-Time Window').item.json;
return [{ json: { ...prior, xeroTenantId: tenantId } }];

const resp = $input.item.json;
const prior = $('Extract Tenant ID').item.json;
const invoices = resp.Invoices || [];
return [{ json: { ...prior, isDuplicate: invoices.length > 0, existingInvoiceId: invoices[0] ? invoices[0].InvoiceID : null } }];

const d = $input.item.json;
return [{ json: {
  status: 'skipped',
  reason: 'duplicate_invoice',
  jobId: d.jobId,
  invoiceReference: d.invoiceReference,
  existingInvoiceId: d.existingInvoiceId,
} }];

const resp = $input.item.json;
const prior = $('Check Duplicate Result').item.json;
const contacts = resp.Contacts || [];
return [{ json: { ...prior, contactFound: contacts.length > 0, existingContactId: contacts[0] ? contacts[0].ContactID : null } }];

const resp = $input.item.json;
const prior = $('Contact Search Result').item.json;
const contact = (resp.Contacts || [])[0] || {};
return [{ json: { ...prior, resolvedContactId: contact.ContactID || null, contactResolution: 'created' } }];

const resp = $input.item.json;
const prior = $('Contact Resolved').item.json;
const invoice = (resp.Invoices || [])[0] || {};
return [{ json: { ...prior, invoiceId: invoice.InvoiceID || null, invoiceNumber: invoice.InvoiceNumber || null, invoiceStatusResult: invoice.Status || null } }];

